const evidence = {
    feature: 'Feature tests execute the application boundary and assert the resulting business state.',
    postgres: 'PostgreSQL integration tests assert constraints, transactions, tenant scope or concurrency.',
    browser: 'Hosted Playwright exercises the visible page, action, persisted result and refresh path.',
    staging: 'The isolated staging acceptance identity executed the bounded real workflow and the resulting records were read back.',
    external: 'The configured staging provider or acceptance identity is unavailable for a safe real-provider execution.',
};

function capability(id, area, actor, surface, state, action, proofType, testName, evidenceText, status = 'VERIFIED', notes = '', overrides = {}) {
    const proof = evidence[proofType] ?? proofType;

    return {
        ID: id,
        Area: area,
        Actor: actor,
        Surface: surface,
        'Page/state': state,
        'Action/button': action,
        Preconditions: overrides.preconditions ?? `Authorized ${actor.toLowerCase()}; active organization context; valid record for ${action.toLowerCase()}.`,
        'Visible when': overrides.visible ?? `The ${action.toLowerCase()} control is shown in the stated state and permission scope.`,
        'Hidden/denied when': overrides.hidden ?? 'Unauthenticated, wrong organization, missing permission, invalid input or disallowed state.',
        'Input variants': overrides.input ?? 'Valid input; missing required value; malformed/expired value; refresh/back; repeat submit.',
        'Expected state change': overrides.state ?? `${action} produces the documented state transition or a human validation error without a partial transition.`,
        'Expected DB effect': overrides.db ?? 'Authoritative rows, history/audit and idempotency records are committed once in the current organization.',
        'Expected notification/message': overrides.notification ?? 'Only the configured transactional or marketing event is emitted; suppressed events are recorded with a reason.',
        'Expected UI after action': overrides.ui ?? 'Success or human error is visible, the action state is refreshed, and a reload shows the persisted result.',
        'Reverse/correction path': overrides.reverse ?? 'The supported cancel, correction or retry path preserves history and restores the invariant.',
        'Retry/idempotency behavior': overrides.retry ?? 'A repeated request with the same idempotency key is safe and does not duplicate the business effect.',
        'Concurrency behavior': overrides.concurrency ?? 'Concurrent requests preserve the invariant; stale versions or leases are rejected or reclaimed safely.',
        'Tenant/security behavior': overrides.security ?? 'Organization context and authorization are derived server-side; foreign identifiers and protected data are denied.',
        'Test type': overrides.testType ?? proofType,
        'Test name': testName,
        'Evidence/run': `${proof} ${evidenceText}`,
        Status: status,
        Notes: notes,
    };
}

