export const canonicalById = new Map(canonicalCapabilities.map((capability) => [capability.ID, capability]));

function match(id, reason, classification = 'DUPLICATE') {
    return { canonical: id, classification, reason };
}

function internal(reason) {
    return { canonical: '—', classification: 'INTERNAL', reason };
}

function areaId(path) {
    const matchResult = path.match(/app\/Filament\/Resources\/([^/]+)|app\/Modules\/([^/]+)/);
    return matchResult?.[1] ?? matchResult?.[2] ?? '';
}

function mapCrm(path, action) {
    const value = `${path} ${action}`.toLowerCase();
    if (value.includes('booking')) return match('BOOKING-CRM-CREATE', 'CRM Booking resource/page/action declarations are representations of the CRM booking flow.');
    if (value.includes('financialobligation') || value.includes('finance')) return match('FINANCE-OBLIGATION', 'CRM Finance resource/page/action declarations are representations of obligation/payment flows.');
    if (value.includes('giftcertificate')) return match('GIFT-SALE', 'CRM Gift Certificate resource/page/action declarations are representations of sale/issue/history flows.');
    if (value.includes('referralpayout') || value.includes('payout')) return match('PARTNER-PAYOUT', 'CRM payout declarations are representations of the partner payout lifecycle.');
    if (value.includes('referralpartner') || value.includes('partner')) return match('PARTNER-LIFECYCLE', 'CRM partner declarations are representations of partner lifecycle/cabinet flows.');
    if (value.includes('referralrelationship') || value.includes('referral')) return match('REFERRAL-ATTRIBUTION', 'CRM referral declarations are representations of attribution/reward relationship flows.');
    if (value.includes('medicalsession') || value.includes('session')) return match('SESSION-COCKPIT', 'CRM session declarations are representations of the session cockpit.');
    if (value.includes('client')) return match('CRM-CLIENT-CRUD', 'Client routes, screens, actions and relation managers share the client/cockpit capability.');
    if (value.includes('specialistservice')) return match('CRM-SPECIALIST-SERVICE', 'Assignment declarations share the specialist-service capability.');
    if (value.includes('specialist')) return match('CRM-SPECIALIST-CRUD', 'Specialist declarations share the specialist CRUD capability.');
    if (value.includes('workinglocation') || value.includes('locationday')) return match('CRM-LOCATIONS-DAYS', 'Location declarations share the working-location/day capability.');
    if (value.includes('scheduleexception')) return match('CRM-SCHEDULE-EXCEPTIONS', 'Schedule exception declarations share the exception capability.');
    if (value.includes('unavailableperiod')) return match('CRM-UNAVAILABLE-PERIODS', 'Unavailable-period declarations share the blocking capability.');
    if (value.includes('service')) return match('CRM-SERVICE-CRUD', 'Service declarations share the catalog capability.');
    if (value.includes('surveyattempt')) return match('SURVEY-REPORT', 'Survey attempt declarations share the report/history capability.');
    if (value.includes('surveydefinition')) return match('SURVEY-DEFINITIONS', 'Survey definition declarations share the definition capability.');
    if (value.includes('knowledge')) return match('KNOWLEDGE-SOURCE', 'Knowledge declarations share source/revision/inspector capabilities.');
    if (value.includes('content')) return match('CONTENT-SECTIONS', 'Content declarations share the content section capability.');
    if (value.includes('legal')) return match('LEGAL-PUBLISH', 'Legal declarations share publication/history capability.');
    if (value.includes('feedback')) return match('FEEDBACK-SUBMIT', 'Feedback declarations share feedback submission/review capability.');
    if (value.includes('tracker')) return match('TRACKER-PLAN', 'Tracker declarations share plan/enrollment capability.');
    if (value.includes('b2b')) return match('B2B-LEAD', 'B2B declarations share lead/call capability.');
    if (value.includes('broadcast')) return match('BROADCAST-CREATE', 'Broadcast declarations share campaign/audience capability.');
    if (value.includes('scenario')) return match('SCENARIO-RULES', 'Scenario declarations share rule/action/history capability.');
    if (value.includes('notification')) return match('NOTIFICATION-TRANSACTIONAL', 'Notification declarations share catalog/template/delivery capability.');
    if (value.includes('ai')) return match('AI-PROVIDERS', 'AI administration declarations share provider/prompt/run/evaluation capability.');
    if (value.includes('dashboard') || value.includes('analytic')) return match('ANALYTICS-DASHBOARD', 'Dashboard/analytics declarations share the metrics capability.');
    if (value.includes('message') || value.includes('companion')) return match('MESSAGE-CRM-VIEW', 'CRM message/Companion declarations share the conversation workspace capability.');
    if (value.includes('workschedule') || value.includes('scheduling')) return match('CRM-WORK-SCHEDULE', 'Scheduling page declarations share the work schedule/configuration capability.');
    return internal(`Framework declaration under ${areaId(path) || 'CRM'} has no distinct user-observable flow beyond its mapped resource surface.`);
}

function mapPortal(path, action) {
    const value = `${path} ${action}`.toLowerCase();
    if (value.includes('companion')) return match('COMPANION-AI-REPLY', 'Portal Companion controls share the AI/handoff flow.');
    if (value.includes('booking')) return value.includes('reschedule') ? match('BOOKING-RESCHEDULE', 'Portal booking reschedule controls share the reschedule capability.') : match('BOOKING-PORTAL-OFFICE', 'Portal booking controls share the booking creation/detail capability.');
    if (value.includes('gift')) return value.includes('claim') ? match('GIFT-CLAIM', 'Gift claim controls share the claim capability.') : match('GIFT-TRANSFER', 'Gift portal controls share the holder/transfer/redeem capability.');
    if (value.includes('finance')) return match('FINANCE-PORTAL-PAYMENT', 'Portal finance controls share the payment/debt capability.');
    if (value.includes('referral')) return match('REFERRAL-ATTRIBUTION', 'Portal referral controls share attribution/reward/cabinet capability.');
    if (value.includes('survey')) return value.includes('report') ? match('SURVEY-REPORT', 'Portal survey report controls share the report capability.') : match('SURVEY-START', 'Portal survey controls share start/progress/submit capability.');
    if (value.includes('tracker')) return match('TRACKER-ENROLLMENT', 'Portal tracker controls share enrollment/check-in/task capability.');
    if (value.includes('feedback')) return match('FEEDBACK-SUBMIT', 'Portal feedback controls share submission capability.');
    if (value.includes('b2b')) return match('B2B-LEAD', 'Portal B2B controls share lead/segmentation capability.');
    if (value.includes('profile') || value.includes('onboarding')) return match('IDENTITY-PROFILE', 'Portal profile/onboarding controls share profile capability.');
    if (value.includes('section') || value.includes('content')) return match('CONTENT-SECTIONS', 'Portal content controls share section rendering capability.');
    if (value.includes('health')) return match('MEDICAL-PROFILE', 'Portal health controls share authorized medical profile capability.');
    if (value.includes('locale') || value.includes('more') || value.includes('home')) return match('CONTENT-RU-EN', 'Portal shell/navigation controls share localized client shell capability.');
    return internal('Portal control is a presentation/navigation representation without a distinct business transition.');
}

function mapHttp(action) {
    const value = action.toLowerCase();
    if (value.includes('/portal/auth/email')) return match('IDENTITY-PORTAL-EMAIL', 'Email auth endpoints are the request/verify representation.');
    if (value.includes('/portal/auth/telegram') || value.includes('/portal/telegram/auth')) return match('IDENTITY-PORTAL-TELEGRAM', 'Telegram auth endpoints are the signed Mini App/linking representation.');
    if (value.includes('/portal/bookings')) return value.includes('reschedule') ? match('BOOKING-RESCHEDULE', 'Portal reschedule route is the booking reschedule representation.') : value.includes('cancel') ? match('BOOKING-CLIENT-CANCEL', 'Portal cancel route is the client cancellation representation.') : match('BOOKING-PORTAL-OFFICE', 'Portal booking routes are the client booking representation.');
    if (value.includes('/gift-certificates')) return value.includes('claim') ? match('GIFT-CLAIM', 'Gift claim routes are the claim representation.') : match('GIFT-TRANSFER', 'Gift portal routes are holder/transfer/apply representations.');
    if (value.includes('/portal/finance')) return match('FINANCE-PORTAL-PAYMENT', 'Portal finance routes are the client payment/debt representation.');
    if (value.includes('/portal/referrals') || value.includes('/r/')) return match('REFERRAL-ATTRIBUTION', 'Referral routes are attribution/cabinet representations.');
    if (value.includes('/portal/survey')) return value.includes('report') ? match('SURVEY-REPORT', 'Survey report route is the report representation.') : match('SURVEY-START', 'Survey routes are start/progress/submit representations.');
    if (value.includes('/portal/tracker')) return match('TRACKER-ENROLLMENT', 'Tracker routes are enrollment/check-in/task representations.');
    if (value.includes('/portal/companion')) return match('COMPANION-AI-REPLY', 'Companion routes are the AI/handoff representation.');
    if (value.includes('/portal/feedback')) return match('FEEDBACK-SUBMIT', 'Feedback routes are the client submission representation.');
    if (value.includes('/portal/b2b')) return match('B2B-LEAD', 'B2B routes are lead/segmentation representations.');
    if (value.includes('/portal/health') || value.includes('/portal/medical')) return match('MEDICAL-PROFILE', 'Portal health/file routes are authorized medical representations.');
    if (value.includes('/portal/profile') || value.includes('/portal/onboarding')) return match('IDENTITY-PROFILE', 'Portal profile/onboarding routes are profile representations.');
    if (value.includes('/portal/sections')) return match('CONTENT-SECTIONS', 'Portal section route is the content representation.');
    if (value.includes('/webhooks/lava')) return match('PAYMENT-LAVA-EXTERNAL', 'Lava webhook route is the external gateway representation.');
    if (value.includes('/admin/clients') && value.includes('companion')) return match('COMPANION-STAFF-HANDOFF', 'CRM Companion endpoint is the staff takeover/reply representation.');
    if (value.includes('/admin/attachments') || value.includes('/medical-attachments')) return match('MEDICAL-ATTACHMENTS', 'Private attachment route is the authorized file representation.');
    if (value.includes('/knowledge/')) return match('KNOWLEDGE-INSPECTOR', 'Knowledge download/inspection route is the source/revision representation.');
    if (value.includes('/admin/broadcasts')) return match('BROADCAST-SEND', 'Broadcast media route is the bounded campaign representation.');
    if (value.includes('/admin/b2b')) return match('B2B-ZOOM', 'B2B meeting route is the provider lifecycle representation.');
    if (value.includes('/admin/ai-runs')) return match('AI-RUNS', 'AI run export route is the protected run representation.');
    return internal('Health or framework route has no distinct acceptance capability.');
}

export function mapSourceDeclaration(row) {
    const value = `${row.path} ${row.action}`.toLowerCase();
    if (row.kind === 'HTTP') return mapHttp(row.action);
    if (row.kind === 'PORTAL-CONTROL') return mapPortal(row.path, row.action);
    if (row.kind === 'CRM-CONTROL') return mapCrm(row.path, row.action);
    if (['CRM-RESOURCE', 'CRM-PAGE', 'CRM-SCREEN', 'CRM-NAV', 'CRM-ACTION', 'CRM-FORM', 'CRM-SUBMIT'].includes(row.kind)) return mapCrm(row.path, row.action);
    if (row.kind === 'METRIC') return match('ANALYTICS-DASHBOARD', 'Widget metric declarations are representations of dashboard analytics.');
    if (row.kind === 'NOTIFICATION') return match('NOTIFICATION-TRANSACTIONAL', 'Catalog event declarations map to notification contracts; delivery is proven by notification tests.');
    if (row.kind === 'TELEGRAM') return match('TELEGRAM-CLIENT-EXTERNAL', 'Telegram handlers are inbound/client channel representations; staff outbound is a separate capability.');
    if (row.kind === 'TELEGRAM-BUTTON' || row.kind === 'TELEGRAM-MENU') return match('TELEGRAM-STAFF', 'Keyboard/menu declarations are channel presentation representations; destination flow is mapped separately.');
    if (row.kind === 'STATE') {
        if (value.includes('booking')) return match('BOOKING-STATE', 'Enum member is a reference representation of the booking state machine.');
        if (value.includes('gift') || value.includes('certificate')) return match('GIFT-CONCURRENCY', 'Enum member is a reference representation of gift lifecycle invariants.');
        if (value.includes('payment') || value.includes('obligation') || value.includes('purchase') || value.includes('fulfillment')) return match('FINANCE-OBLIGATION', 'Enum member is a reference representation of finance/commerce state.');
        if (value.includes('survey')) return match('SURVEY-IMMUTABILITY', 'Enum member is a reference representation of survey attempt state.');
        if (value.includes('broadcast')) return match('BROADCAST-SEND', 'Enum member is a reference representation of broadcast lifecycle.');
        if (value.includes('scenario') || value.includes('delivery')) return match('SCENARIO-HISTORY', 'Enum member is a reference representation of scenario/delivery state.');
        if (value.includes('ai') || value.includes('companion')) return match('COMPANION-AI-REPLY', 'Enum member is a reference representation of AI/Companion lifecycle.');
        if (value.includes('knowledge') || value.includes('ingest') || value.includes('revision')) return match('KNOWLEDGE-INGEST', 'Enum member is a reference representation of ingestion state.');
        if (value.includes('feedback')) return match('FEEDBACK-ROUTING', 'Enum member is a reference representation of feedback state.');
        if (value.includes('partner') || value.includes('payout') || value.includes('referral')) return match('PARTNER-PAYOUT', 'Enum member is a reference representation of referral/partner state.');
        if (value.includes('tracker')) return match('TRACKER-ENROLLMENT', 'Enum member is a reference representation of tracker state.');
        return internal('Enum reference is not independently user-observable and is retained as source coverage only.');
    }
    if (row.kind === 'ADAPTER') {
        if (value.includes('zoom')) return match('ZOOM-ADAPTER', 'Adapter declaration is the configured Zoom implementation behind the lifecycle capability.');
        if (value.includes('telegram')) return match('TELEGRAM-STAFF', 'Adapter declaration is the Telegram channel implementation behind mapped flows.');
        if (value.includes('lava')) return match('PAYMENT-LAVA-EXTERNAL', 'Adapter declaration is the Lava external implementation.');
        if (value.includes('email')) return match('EMAIL-APP-OTP', 'Adapter declaration is the configured application email implementation.');
        return internal('Adapter declaration is an internal port implementation represented by its user-visible flow.');
    }
    if (row.kind === 'WIRING') return internal('Dependency wiring is infrastructure evidence, not an independent acceptance action.');
    if (row.kind === 'JOB') return match(value.includes('companion') ? 'COMPANION-AI-REPLY' : value.includes('knowledge') ? 'KNOWLEDGE-INGEST' : value.includes('broadcast') ? 'BROADCAST-SEND' : value.includes('referral') ? 'REFERRAL-CREDIT' : value.includes('scenario') ? 'SCENARIO-ACTIONS' : value.includes('b2b') || value.includes('booking') ? 'BOOKING-ZOOM-LIFECYCLE' : 'QUEUE-HORIZON', 'Queue job is a durable execution representation of the mapped capability.');
    if (row.kind === 'COMMAND' || row.kind === 'SCHEDULER') return row.kind === 'SCHEDULER' ? match('SCHEDULER', 'Scheduler declaration is the scheduled operations representation.') : internal('Console command is an operational/internal execution surface represented by its domain capability.');
    return internal('Source declaration is outside the user-observable acceptance surface and is retained for completeness.');
}
